// Definition for a Node.
class Node {
public:
    int val;
    Node* prev;
    Node* next;
    Node* child;
};
*/

class Solution {
public:
    Node* flatten(Node* head) {
        if(!head) return head;
        Node* last = head;
        Node* cur = head;
        Node* branchPtrArr[1010];
        int top = 0;

        branchPtrArr[0] = head;
        top++;

        // 그리고 child에서 탐색
        // child에서 nullptr까지 도달하면, 종료
        while (top)
        {
            while (cur)
            {
                // 만약 child가 있는 노드를 만나면
                // branchPtrArr에 cur-&gt;next 노드 추가
                if (cur-&gt;child)
                {
                    if (cur-&gt;next)
                    {
                        branchPtrArr[top] = cur-&gt;next;
                        top++;
                    }
                    cur-&gt;next = cur-&gt;child;
                    cur-&gt;next-&gt;prev = cur;
                    cur-&gt;child = nullptr;
                }

                if (!(cur-&gt;next))
                {
                    if (top == 1) top--;
                    if (top&gt;1)
                    {
                        last = branchPtrArr[top - 1];
                        cur-&gt;next = last;
                        last-&gt;prev = cur;
                        top--;
                    }
                }
                // 오른쪽으로 가기
                cur = cur-&gt;next;
            }
        }

        return head;
    }
};
